(self.webpackChunksite=self.webpackChunksite||[]).push([[855],{3177:e=>{"use strict";e.exports=JSON.parse('{"slug":"cheddar","title":"Cheddar","authors":[{"name":"Diego Pimenta Su\xe1rez","contact":"Diegolinop","contactType":"github","contactUrl":"https://github.com/Diegolinop"}],"date":1783900800000,"readme":"<p>A rat, a dark sewer, and a whole lot of cheese. Explore room by room, eat your way past locked doors, and make your way deeper in.</p>\\n<p>It starts simple enough, but things aren\'t quite what they seem.</p>\\n<h2>Controls</h2>\\n<ul>\\n<li><strong>\u2b05\ufe0f \u27a1\ufe0f</strong>: Move</li>\\n<li><strong>\u2b06\ufe0f</strong>: Jump</li>\\n<li><strong>X</strong>: Confirm / advance</li>\\n</ul>\\n<h2>Credits</h2>\\n<p>Made as a project for the Systems Programming course within the Computer Science undergraduate program at the State University of Maring\xe1 (UEM). Supervised by Professor Marcelo de Gomensoro Malheiros.</p>"}')}}]);